"""Generate DIAGNOSTICS.md from separate finite diagnostic runs; no rankings."""
import collections
import hashlib
import json
import statistics
from pathlib import Path

ROOT = Path(__file__).resolve().parent
lines = ['# Record lookup: separate diagnostic confirmations', '',
         'Generated by diagnostics.py; do not edit tables. These datasets, budgets and engine runs remain separate. Ratios are frozen/candidate latency (>1 favors record). Ranges are full process ranges, not confidence intervals. No competitor or universal rankings are derived here.', '']

def ranged(xs, digits=3):
    return f'{statistics.median(xs):.{digits}f} [{min(xs):.{digits}f}, {max(xs):.{digits}f}]'

def paired(name, title):
    path = ROOT / name
    r = json.loads(path.read_text())
    assert r['complete'] is True
    assert r['configuration']['rounds'] == 5
    assert len(r['samples']) == 10
    assert r['runtime']['version'] == 'v26.12.0' and r['runtime']['bun'] is None
    c = r['configuration']
    rows = collections.defaultdict(list)
    for round in range(5):
        ss = {s['variant']: s for s in r['samples'] if s['round'] == round}
        assert set(ss) == {'frozen', 'candidate'}
        for sample in ss.values():
            assert sample['verification']['passed']
            for m in sample['measurements']:
                assert m['warmup']['elapsedMs'] >= c['warmMs'] and m['warmup']['calls'] >= c['warmCalls']
                assert m['elapsedMs'] >= c['minMs'] and m['calls'] >= 5
                assert abs(m['elapsedMs'] / m['calls'] - m['ms']) < 1e-9
        a = {(m['id'],m['mode'],m['operation']):m['ms'] for m in ss['frozen']['measurements']}
        for m in ss['candidate']['measurements']:
            k = m['id'],m['mode'],m['operation']
            rows[k].append(a[k] / m['ms'])
    lines.extend(['## ' + title, '',
        f"Five opposite-order fresh-process pairs, {c['warmMs']}ms warmup and {c['minMs']}ms measurement per document/mode/operation. Raw SHA256: `{hashlib.sha256(path.read_bytes()).hexdigest()}`.", '',
        '| Document | Mode | Operation | Ratio median [min, max] |',
        '| --- | --- | --- | ---: |'])
    for (doc,mode,op), values in rows.items():
        lines.append(f'| {doc} | {mode} | {op} | {ranged(values)} |')
    if name == 'legacy.json':
        lines.extend(['', '**Original compatibility score uses arithmetic mean latency, not the geometric mean of speedups. UnicodeRandom regresses while LatinRepeat improves; the arithmetic aggregate is nearly flat. This run does not re-rank any other tokenizer.**', '',
            '| Operation | Frozen mean ms/call | Record mean ms/call | Paired mean-latency ratio |',
            '| --- | ---: | ---: | ---: |'])
        for op in c['operations']:
            v = {e:[] for e in ['frozen','candidate']}
            for i in range(5):
                for e in v:
                    s = next(s for s in r['samples'] if s['round']==i and s['variant']==e)
                    v[e].append(statistics.mean(m['ms'] for m in s['measurements'] if m['operation']==op))
            lines.append(f"| {op} | {ranged(v['frozen'])} | {ranged(v['candidate'])} | {ranged([a/b for a,b in zip(v['frozen'],v['candidate'])])} |")
    lines.append('')

paired('legacy.json', 'Original seven inputs: Node/o200k')
paired('guards.json', 'Longer support, European and README guards: Node/o200k')
r = json.loads((ROOT/'churn.json').read_text())
assert r['complete'] and r['capacity']==100000 and r['words']==500000 and len(r['rows'])==8
lines.extend(['## Sustained unique-piece churn', '',
    'Default100k capacity; 500k distinct eight-letter ASCII pieces, 500 words per request:100k fill and four100k unique churn cycles. Two opposite-order pairs per engine, with an independent tiktoken1.0.22 exact-ID oracle. All blocks passed exact encode/count and bounded-cache/ownership checks. This deliberately adverse workload is not a realistic traffic model or a headline score. Count runs immediately after each encode and therefore measures warm pieces.', '',
    '**Unconditional record replacement is rejected:** Bun slows materially during sustained deletion/rehash despite lower retained memory. Node is faster in earlier phases and near parity in the final phase. Node/cl100k churn was not measured.', '',
    '| Engine | Phase | Frozen encode ms | Record encode ms | Paired ratio | Frozen post-GC heap MiB | Record post-GC heap MiB |',
    '| --- | ---: | ---: | ---: | ---: | ---: | ---: |'])
for engine in ['Node26.12.0','Bun1.4.3']:
    rows=[s for s in r['rows'] if bool(s['runtime']['bun'])==(engine=='Bun1.4.3')]
    assert len(rows)==4
    assert all(s['exactTokens'] and s['bounded'] for s in rows)
    for phase in range(5):
        ss={e:[s['phases'][phase] for s in rows if s['variant']==e] for e in ['frozen','candidate']}
        assert all(p['cacheSize']==100000 for values in ss.values() for p in values)
        a=[s['encodeMs'] for s in ss['frozen']];b=[s['encodeMs'] for s in ss['candidate']]
        heap={e:[s['memory']['heapUsed']/1048576 for s in values] for e,values in ss.items()}
        lines.append(f"| {engine} | {phase} | {ranged(a,1)} | {ranged(b,1)} | {ranged([x/y for x,y in zip(a,b)])} | {ranged(heap['frozen'],2)} | {ranged(heap['candidate'],2)} |")
lines.extend(['', '| Engine | Variant | Final settled RSS MiB | Sampled peak RSS MiB | process.resourceUsage maxRSS MiB |',
              '| --- | --- | ---: | ---: | ---: |'])
for engine in ['Node26.12.0','Bun1.4.3']:
    for variant in ['frozen','candidate']:
        ss=[s for s in r['rows'] if bool(s['runtime']['bun'])==(engine=='Bun1.4.3') and s['variant']==variant]
        lines.append('| '+ ' | '.join([engine,variant,ranged([s['phases'][-1]['memory']['rss']/1048576 for s in ss],2),ranged([s['peakSampledRSS']/1048576 for s in ss],2),ranged([s['maxRSSKiB']/1024 for s in ss],2)])+' |')
lines.extend(['', 'Resource accounting includes the identical deterministic corpus/oracle and block buffers in each process. Cross-engine GC/allocator counters differ; compare variants within the same engine. Forced GC occurs after each phase, outside operation timers. Dynamic Map capacity growth makes high-churn retained memory differ from the fresh-initialization heap tradeoff; both are reported.', '',
    f"Corpus SHA256: `{r['corpusSHA256']}`. Oracle binary SHA256: `{r['oracleSHA256']}`. The archived generator deterministically regenerates both; no large input or oracle binary is required in git.", ''])
(ROOT/'DIAGNOSTICS.md').write_text('\n'.join(lines))
